-- 按 希纳斯.xlsx 掉落页重建 Boss 掉落（扎昆除外）。
-- 多形态 Boss 仅在最终（通关）形态掉落；DELETE 覆盖全部形态以防残留。
-- chance 基准 1000000。
DELETE FROM `drop_data`
WHERE `dropperid` IN (8645009,8840000,8840001,8850011,8860000,8880000,8880110,8880111,8880140,8880141,8880300,8880301,8880302,8880340,8880341,8880342,8880343,8880344,8880400,8880700,8880803,8900000,8900001,8900002,8910000,8920000,8920001,8920002,8930000,9400265,9400266,9400271,9400289,9400294,9400300,9400409,9420522,9421581,9421583,9450040,9600087);

ON DUPLICATE KEY UPDATE
    `minimum_quantity` = VALUES(`minimum_quantity`),
    `maximum_quantity` = VALUES(`maximum_quantity`),
    `questid` = VALUES(`questid`),
    `chance` = VALUES(`chance`);
